<script setup lang="ts">
import { Head } from '@inertiajs/vue3'
import { onMounted,onUnmounted,ref } from 'vue'
import StatCard from '../Components/ui/StatCard.vue'
const props=defineProps<{latest:any;activity:Record<string,number>;queuedBroadcasts:number;history:any[]}>()
const latest=ref(props.latest),activity=ref(props.activity),queuedBroadcasts=ref(props.queuedBroadcasts),history=ref([...props.history])
let stream:EventSource|undefined
onMounted(()=>{stream=new EventSource('/metrics/stream');stream.addEventListener('metrics',(event)=>{const data=JSON.parse((event as MessageEvent).data);if(data){latest.value=data;history.value=[...history.value,data].slice(-120)}})})
onUnmounted(()=>stream?.close())
const ram=()=>latest.value?.ram_total_bytes?Math.round(latest.value.ram_used_bytes/latest.value.ram_total_bytes*100):0
const disk=()=>latest.value?.disk_total_bytes?Math.round(latest.value.disk_used_bytes/latest.value.disk_total_bytes*100):0
const trend=()=>history.value.map((x,i)=>{const max=Math.max(1,...history.value.map(y=>Number(y.cpu_percent||0)));return (i*100/(history.value.length-1||1))+','+(100-Number(x.cpu_percent||0)*100/max)}).join(' ')
</script>
<template><Head title="داشبورد Matrix Synapse"/><v-container fluid class="pa-6"><div class="d-flex align-center justify-space-between mb-5"><div><h1 class="text-h4">نمای کلی سامانه</h1><div class="text-medium-emphasis">آخرین به‌روزرسانی: {{ latest?.sampled_at||'در انتظار اولین نمونه‌برداری' }}</div></div><v-chip color="success" variant="tonal">نمونه‌برداری ۱۵ ثانیه‌ای</v-chip></div><v-row><v-col cols="6" md="3"><StatCard title="کل کاربران" :value="latest?.users_total??'—'" icon="mdi-account-group" to="/users"/></v-col><v-col cols="6" md="3"><StatCard title="اتاق‌ها" :value="latest?.rooms_total??'—'" icon="mdi-forum" to="/rooms"/></v-col><v-col cols="6" md="3"><StatCard title="فعال در ۵ دقیقه اخیر" :value="latest?.online_users??'—'" icon="mdi-account-clock"/></v-col><v-col cols="6" md="3"><StatCard title="پیام‌های در صف" :value="queuedBroadcasts" icon="mdi-bullhorn" to="/broadcasts"/></v-col></v-row><v-row class="mt-1"><v-col cols="12" md="4"><v-card rounded="xl" class="pa-5 text-center"><div class="text-subtitle-1 mb-3">CPU</div><v-progress-circular :model-value="latest?.cpu_percent||0" :size="120" :width="11" color="primary">{{ Number(latest?.cpu_percent||0).toFixed(1) }}%</v-progress-circular></v-card></v-col><v-col cols="12" md="4"><v-card rounded="xl" class="pa-5 text-center"><div class="text-subtitle-1 mb-3">RAM</div><v-progress-circular :model-value="ram()" :size="120" :width="11" color="primary">{{ ram() }}%</v-progress-circular></v-card></v-col><v-col cols="12" md="4"><v-card rounded="xl" class="pa-5 text-center"><div class="text-subtitle-1 mb-3">Disk</div><v-progress-circular :model-value="disk()" :size="120" :width="11" color="primary">{{ disk() }}%</v-progress-circular></v-card></v-col></v-row><v-row><v-col cols="12" md="8"><v-card rounded="xl" class="pa-5"><v-card-title>روند مصرف CPU</v-card-title><svg viewBox="0 0 100 100" preserveAspectRatio="none" width="100%" height="150"><polyline :points="trend()" fill="none" stroke="currentColor" stroke-width="1.5" vector-effect="non-scaling-stroke"/></svg></v-card></v-col><v-col cols="12" md="4"><v-card rounded="xl" class="pa-5"><v-card-title>دسته‌بندی فعالیت</v-card-title><v-list density="compact"><v-list-item v-for="key in ['heavy_active','active','low_active','dormant','suspicious']" :key="key" :title="key" :append-title="String(activity[key]||0)"/></v-list></v-card></v-col></v-row><v-card rounded="xl" class="pa-4 mt-4"><v-card-title>دسترسی سریع</v-card-title><v-card-actions class="flex-wrap"><v-btn color="primary" href="/users">کاربران</v-btn><v-btn href="/rooms">اتاق‌ها</v-btn><v-btn href="/media">مدیا و سهمیه‌ها</v-btn><v-btn href="/activity">فعالیت</v-btn><v-btn href="/metrics">مانیتورینگ</v-btn><v-btn href="/broadcasts">ارسال پیام</v-btn><v-btn href="/server">نسخه Synapse</v-btn><v-btn href="/audit-logs">گزارش رویدادها</v-btn></v-card-actions></v-card></v-container></template>
